  function read(key,fallback){try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw):clone(fallback)}catch(e){return clone(fallback)}}
  function write(key,val){localStorage.setItem(key,JSON.stringify(val));return val}
  function uid(prefix='id'){return prefix+'-'+Math.random().toString(36).slice(2,8)+Date.now().toString(36).slice(-4)}
