    if(!localStorage.getItem(KEYS.lots)) write(KEYS.lots, seedLots);
    if(!localStorage.getItem(KEYS.brokers)) write(KEYS.brokers, seedBrokers);
    if(!localStorage.getItem(KEYS.sdrs)) write(KEYS.sdrs, seedSDRs);
    if(!localStorage.getItem(KEYS.leads)) write(KEYS.leads, seedLeads);
    if(!localStorage.getItem(KEYS.occurrences)) write(KEYS.occurrences, seedOccurrences);
    if(!localStorage.getItem(KEYS.tasks)) write(KEYS.tasks, seedTasks);
    if(!localStorage.getItem(KEYS.works)) write(KEYS.works, seedWorks);
    if(!localStorage.getItem(KEYS.conversations)) write(KEYS.conversations, []);
    if(!localStorage.getItem(KEYS.handoffs)) write(KEYS.handoffs, []);
    if(!localStorage.getItem(KEYS.proposals)) write(KEYS.proposals, []);
    if(!localStorage.getItem(KEYS.settings)) write(KEYS.settings, {mvp:'fase 2', version:'4.0 Full'});
