  function brl(v){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v||0))}
  function statusTag(s){return String(s||'').toLowerCase().replaceAll(' ','-').replace('á','a').replace('í','i').replace('ú','u').replace('ç','c').replace('ô','o').replace('ã','a')}
  function lots(){return read(KEYS.lots, seedLots)}
  function leads(){return read(KEYS.leads, seedLeads)}
  function brokers(){return read(KEYS.brokers, seedBrokers)}
  function sdrs(){return read(KEYS.sdrs, seedSDRs)}
  function occurrences(){return read(KEYS.occurrences, seedOccurrences)}
  function tasks(){return read(KEYS.tasks, seedTasks)}
  function works(){return read(KEYS.works, seedWorks)}
  function conversations(){return read(KEYS.conversations, [])}
  function handoffs(){return read(KEYS.handoffs, [])}
  function proposals(){return read(KEYS.proposals, [])}
