  function saveLeads(v){return write(KEYS.leads,v)}
  function saveBrokers(v){return write(KEYS.brokers,v)}
  function saveSDRs(v){return write(KEYS.sdrs,v)}
  function saveOccurrences(v){return write(KEYS.occurrences,v)}
  function saveTasks(v){return write(KEYS.tasks,v)}
  function saveWorks(v){return write(KEYS.works,v)}
  function saveHandoffs(v){return write(KEYS.handoffs,v)}
